<script setup lang="ts">
import {computed} from 'vue';
import type {Person,Language,World,Hobby} from '../../../packages/shared/src/types';
import {educationView,enrollmentLength} from '../../../packages/engine/src/education';
import {juniorSubjects} from '../../../packages/engine/src/subjects';
const props=defineProps<{person:Person;lang:Language;state?:World}>();
const reports=computed(()=>{const e=props.state?educationView(props.state,props.person):null;if(e?.enrollment&&!e.active)return [];return (props.person.life?.reports??[]).filter(r=>!e?.enrollment||r.date>=`${e.enrollment.startYear}-09-01`&&r.date<`${e.enrollment.startYear+enrollmentLength(e.enrollment)}-07-01`).slice().reverse();});
const labels:Record<Hobby,[string,string]>={reading:['閱讀','Reading'],music:['音樂','Music'],sports:['運動','Sports'],coffee:['咖啡','Coffee'],film:['電影','Film'],drawing:['繪畫與文具','Drawing'],travel:['旅行','Travel'],cooking:['料理','Cooking'],hiking:['登山','Hiking'],camping:['露營','Camping'],sup:['SUP','SUP'],gaming:['遊戲','Gaming'],animation:['動畫製作','Animation'],photography:['攝影','Photography'],japanese:['日語','Japanese'],tea:['茶道','Tea'],railway:['鐵路研究','Railway research'],chess:['棋藝','Chess'],calligraphy:['書法','Calligraphy']};
</script>
<template><details class="student-records"><summary>{{lang==='zh'?'成績單與升學紀錄':'Report cards and admission records'}}</summary><p>{{lang==='zh'?'只顯示目前階段；已完成階段可在歷史區查看。':'Current stage only; completed stages are retained in History.'}}</p><p v-if="!reports.length">{{lang==='zh'?'尚無本階段段考紀錄':'No current-stage term reports'}}</p><details v-for="report in reports" :key="report.date"><summary>{{report.date}} · {{lang==='zh'?`第${report.semester}學期 第${report.exam}次段考`:`Semester ${report.semester}, examination ${report.exam}`}}</summary><p v-if="report.rank">校排 {{report.rank}} / {{report.cohort}}</p><div v-for="(label,key) in juniorSubjects" :key="key" class="skill-row"><span>{{label[lang]}}</span><span>D20 {{report.subjects[key].die}} + {{report.subjects[key].proficiency}}</span><b>{{report.subjects[key].score}} {{lang==='zh'?'分':'points'}}</b></div></details><p v-if="person.life?.cap">{{lang==='zh'?'會考：':'CAP: '}}{{person.life.cap.summary}}</p><details v-for="(round,i) in person.life?.university?.rounds" :key="i"><summary>{{round.name[lang]}} · {{round.total}}</summary><p v-for="(score,subject) in round.scores" :key="subject">{{subject==='mathA'?(lang==='zh'?'數A':'Mathematics A'):subject==='mathB'?(lang==='zh'?'數B':'Mathematics B'):juniorSubjects[subject as keyof typeof juniorSubjects]?.[lang]??subject}}：{{score}} {{lang==='zh'?'級分':'scaled points'}}</p></details></details><details class="hobby-records"><summary>{{lang==='zh'?'興趣與生活技能':'Hobbies and life skills'}}</summary><p v-if="person.life?.workProficiency">{{lang==='zh'?'工作專業':'Professional proficiency'}}：{{person.life.workProficiency}}</p><p v-if="!Object.keys(person.life?.hobbies??{}).length">{{lang==='zh'?'參與生活活動後，經驗會記在這裡。':'Your experience appears here after activities.'}}</p><div v-for="(value,key) in person.life?.hobbies" :key="key" class="skill-row"><span>{{labels[key][lang==='zh'?0:1]}}</span><b>{{value}}</b></div></details></template>
